import functools
def tilings(cells, shapes):
    cells = sorted(cells); idx = {c: i for i, c in enumerate(cells)}; full = (1 << len(cells)) - 1
    place = [set() for _ in cells]
    for shape in shapes:
        for (r, c) in cells:
            for (ar, ac) in shape:
                cs = [(r + dr - ar, c + dc - ac) for dr, dc in shape]
                if all(x in idx for x in cs): place[min(idx[x] for x in cs)].add(sum(1 << idx[x] for x in cs))
    @functools.lru_cache(None)
    def go(mask):
        if mask == full: return 1
        i = next(k for k in range(len(cells)) if not mask >> k & 1)
        return sum(go(mask | m) for m in place[i] if not mask & m)
    return go(0)
DOM = [[(0, 0), (0, 1)], [(0, 0), (1, 0)]]
TEE = [[(0, 0), (0, 1), (0, 2), (1, 1)], [(1, 0), (1, 1), (1, 2), (0, 1)], [(0, 0), (1, 0), (2, 0), (1, 1)], [(0, 1), (1, 1), (2, 1), (1, 0)]]
def board(h, w, gone=()): return {(r, c) for r in range(h) for c in range(w)} - set(gone)
result = tilings(board(4, 4), DOM)

